const { app } = require('electron');
const fs = require('fs');
const os = require('os');
const path = require('path');

// VibeZ 2.0 beta must never reuse or modify the stable 1.x profile.
const stableUserData = app.getPath('userData');
const betaUserData = path.join(path.dirname(stableUserData), 'VibeZ-2.0-test');
app.setPath('userData', betaUserData);

// Keep any Linux autostart file generated by the beta inside an isolated fake home.
// Electron's own standard paths (Downloads, Documents, etc.) are left untouched.
const realHome = os.homedir();
const betaHome = path.join(realHome, '.vibez-2.0-test-home');
fs.mkdirSync(betaHome, { recursive: true });
os.homedir = () => betaHome;

// Test builds must not claim vibez:// or alter OS login-item registration.
app.setAsDefaultProtocolClient = () => false;
app.setLoginItemSettings = () => {};
app.getLoginItemSettings = () => ({ openAtLogin: false });

process.env.VIBEZ_V2_TEST = '1';
require('./main-v2');
